def recall_at_k(retrieved_chunks, relevant_chunk_ids, k):
    # the denominator differs from precision
    top_k = set(retrieved_chunks[:k])
    found_relevant = top_k & relevant_chunk_ids
    return len(found_relevant) / len(relevant_chunk_ids)

def precision_at_k(retrieved_chunks, relevant_chunk_ids, k):
    top_k = retrieved_chunks[:k]
    relevant_count = sum(1 for chunk_id in top_k if chunk_id in relevant_chunk_ids)
    return relevant_count / k

retrieved = ["c1", "c2", "c3", "c4", "c5", "c6", "c7", "c8"]
relevant = {"c1", "c3", "c9"}

# precision recall tradeoff in practice
for k in [3, 5, 8]:
    p_score = precision_at_k(retrieved, relevant, k)
    r_score = recall_at_k(retrieved, relevant, k)
    print(f"K={k}: precision={p_score:.2f}, recall={r_score:.2f}")
